type gatewayObservedStreamBody struct {
	io.ReadCloser
	reads        int
	readingAgain chan struct{}
	closed       chan struct{}
	closeOnce    sync.Once
}

func (body *gatewayObservedStreamBody) Read(p []byte) (int, error) {
	body.reads++
	if body.reads == 2 {
		close(body.readingAgain)
	}
	return body.ReadCloser.Read(p)
}

func (body *gatewayObservedStreamBody) Close() error {
	body.closeOnce.Do(func() { close(body.closed) })
	return body.ReadCloser.Close()
}

type gatewayObservedDeliveryWriter struct {
	*httptest.ResponseRecorder
	delivered chan struct{}
	once      sync.Once
}

func (writer *gatewayObservedDeliveryWriter) Flush() {
	writer.ResponseRecorder.Flush()
	if strings.Contains(writer.Body.String(), "Hello") {
		writer.once.Do(func() { close(writer.delivered) })
	}
}

