			assert.Equal(t, map[string]any{"nanos": "0", "currency": "USD"}, record["receivable"])
			attempts := walletAPIRequest(t, fixture.engine, fixture.adminPAT, http.MethodGet, "/api/admin/v1/requests/"+record["id"].(string)+"/attempts", "")
